  $services=[['social-ads','Social Media Ads','ads'],['music','Music & Video Distro','music'],['verification','Verification','verify'],['web-dev','Web & App Dev','web'],['account-mgmt','Account Management','account'],['press','Press Releases','press'],['smm','Likes & Followers','heart'],['numbers','Virtual Numbers','phone'],['bots','Custom Bots','bot'],['proxies','Proxies','proxy']];
  $reports=[['royalties','/admin/?tab=royalties','Royalties / revenue','chart'],['withdraw','/admin/?tab=withdraw','Withdraw requests','chart'],['emails','/admin/emails','Email notifications','mail']];
  echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="dark"><title>'.$safeTitle.' · TDC Tech Admin</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet"><style>
