</style><link rel="stylesheet" href="/assets/customer-workspace.css?v=20261006b"></head><body><div class="admin-shell"><aside class="sidebar" id="admin-sidebar"><a class="brand" href="/admin/"><span class="logo-mark">'.admin_svg('bolt').'</span><span class="brand-text">TDC Tech</span><span class="admin-pill">ADMIN</span></a><nav class="side-nav"><div class="nav-label">Main</div>';
