function admin_footer(): void {
  echo '<div class="modal" id="invoice-modal" aria-hidden="true"><div class="modal-card"><div class="modal-top"><h3>Invoice</h3><button class="btn small" type="button" onclick="closeInvoiceModal()">Close</button></div><div id="invoice-body"></div><div class="actions invoice-actions"><button class="btn primary" type="button" onclick="window.print()">Print / PDF</button><button class="btn" type="button" onclick="closeInvoiceModal()">Done</button></div></div></div><div class="toast" id="admin-toast"><span id="admin-toast-msg"></span></div></div></main></div><script>(function(){const side=document.getElementById("admin-sidebar"),scrim=document.getElementById("admin-scrim"),toggle=document.getElementById("menu-toggle");function close(){side.classList.remove("open");scrim.classList.remove("open")}if(toggle)toggle.addEventListener("click",()=>{side.classList.toggle("open");scrim.classList.toggle("open")});scrim.addEventListener("click",close);document.querySelectorAll(".side-link").forEach(a=>a.addEventListener("click",close));async function logout(){try{const c=await fetch("/api/csrf.php",{credentials:"same-origin"}).then(r=>r.json());await fetch("/api/auth.php",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json","X-CSRF-Token":c.csrf},body:JSON.stringify({action:"logout"})});}finally{location.href="/admin/login"}}document.getElementById("admin-logout").addEventListener("click",logout);document.getElementById("top-logout").addEventListener("click",logout)})();let __toastTimer;function toast(msg,type="success"){const t=document.getElementById("admin-toast"),m=document.getElementById("admin-toast-msg");if(!t||!m)return;m.textContent=msg;t.className="toast "+(type==="success"?"":type)+" show";clearTimeout(__toastTimer);__toastTimer=setTimeout(()=>t.classList.remove("show"),2800)}function invoiceStore(){try{return JSON.parse(localStorage.getItem("tdcAdminInvoices")||"[]")}catch{return []}}function saveInvoiceStore(rows){localStorage.setItem("tdcAdminInvoices",JSON.stringify(rows.slice(0,200)))}function makeInvoice(orderId,client,service,amount){const id="INV-"+String(orderId).replace(/\D/g,"").padStart(4,"0"),date=new Date().toLocaleDateString("en-GB"),row={id,orderId:String(orderId),client:String(client||"Client"),service:String(service||"Service"),amount:Number(amount||0),date};const rows=invoiceStore();if(!rows.some(x=>x.id===id))saveInvoiceStore([row,...rows]);const body=document.getElementById("invoice-body");body.innerHTML=`<div class="invoice-paper"><div class="invoice-brand"><div><strong>TDC Tech</strong><br><small>Topistar Di Congo · TDC GANGS · TDC TECH</small></div><div style="text-align:right"><strong>${id}</strong><br><small>${date}</small></div></div><div style="margin:24px 0 16px"><small>BILL TO</small><div style="font-weight:800;margin-top:4px">${String(client||"Client").replace(/[<>]/g,"")}</div></div><div class="invoice-line"><span>Service</span><strong>${String(service||"Service").replace(/[<>]/g,"")}</strong></div><div class="invoice-line"><span>Order</span><strong>#${String(orderId)}</strong></div><div class="invoice-line total"><span>Total</span><span>€${Number(amount||0).toFixed(2)}</span></div></div>`;const modal=document.getElementById("invoice-modal");modal.classList.add("open");modal.setAttribute("aria-hidden","false");toast("Invoice created")}function closeInvoiceModal(){const modal=document.getElementById("invoice-modal");modal.classList.remove("open");modal.setAttribute("aria-hidden","true")}</script></body></html>';
}
